'use client';

import React from 'react';
import { X } from 'lucide-react';
import { BlueprintMedia } from '@/types/media';

interface LightboxModalProps {
  item: BlueprintMedia | null;
  isOpen: boolean;
  onClose: () => void;
}

export default function LightboxModal({ item, isOpen, onClose }: LightboxModalProps) {
  if (!isOpen || !item) return null;

  return (
    <div
      onClick={onClose}
      className="fixed inset-0 z-50 bg-[#0e0e10]/95 backdrop-blur-xl flex items-center justify-center p-4 cursor-pointer"
    >
      <div
        onClick={(e) => e.stopPropagation()}
        className="relative max-w-5xl w-full bg-surface-container-low border border-primary/40 rounded-2xl p-4 sm:p-6 shadow-2xl flex flex-col items-center cursor-default"
      >
        <button
          onClick={onClose}
          className="absolute top-4 right-4 w-9 h-9 rounded-full bg-surface-container hover:bg-surface-container-high text-on-surface flex items-center justify-center transition border border-primary/20 cursor-pointer"
          aria-label="Close lightbox"
        >
          <X className="w-5 h-5" />
        </button>

        <img
          src={item.imageUrl}
          alt={item.title}
          className="max-h-[72vh] rounded-xl object-contain border border-primary/20 shadow-2xl mb-4"
        />

        <div className="text-center">
          <h4 className="font-headline-md text-headline-md text-on-surface mb-1">
            {item.title}
          </h4>
          <p className="font-label-sm text-label-sm text-primary uppercase">
            {item.format} • Accession #{item.accessionRef}
          </p>
        </div>
      </div>
    </div>
  );
}
