'use client';

import React from 'react';
import Link from 'next/link';
import { HistoricalAsset } from '@/types/asset';
import { ArrowRight, Box, User, Calendar, MapPin } from 'lucide-react';

interface AssetCardProps {
  asset: HistoricalAsset;
  onSelect?: (asset: HistoricalAsset) => void;
  onExplore?: (asset: HistoricalAsset) => void;
  onExplore3D?: (asset: HistoricalAsset) => void;
}

export default function AssetCard({ asset, onSelect, onExplore, onExplore3D }: AssetCardProps) {
  const handlePrimaryClick = () => {
    if (onSelect) onSelect(asset);
    else if (onExplore) onExplore(asset);
  };

  return (
    // 'h-full' மற்றும் 'flex flex-col' மூலம் அனைத்து கார்டுகளும் ஒரே உயரத்தில் இருக்கும்
    <div className="group relative h-full rounded-2xl bg-[#111111] overflow-hidden flex flex-col transition-all duration-300 hover:-translate-y-1 border border-neutral-800 hover:border-amber-500/50 shadow-xl">
      {/* Card Thumbnail */}
      <div
        className="relative h-56 overflow-hidden bg-[#1A1A1A] flex items-center justify-center cursor-pointer shrink-0"
        onClick={handlePrimaryClick}
      >
        <img
          className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-700 opacity-80 group-hover:opacity-100"
          alt={asset.title}
          src={asset.image}
        />
        <div className="absolute inset-0 bg-gradient-to-t from-[#111111] via-transparent to-transparent" />

        {/* Top Right Badge */}
        <div className="absolute top-4 right-4 flex gap-2">
          <span className="px-2.5 py-1 rounded-md bg-black/60 backdrop-blur-md text-amber-400 font-mono text-[10px] uppercase tracking-wider flex items-center gap-1.5 border border-amber-500/30">
            <span className="w-1.5 h-1.5 rounded-full bg-amber-500 animate-pulse" /> {asset.badge}
          </span>
        </div>
      </div>

      {/* Card Body - flex-1 மூலம் மீதமுள்ள இடத்தை நிரப்பும் */}
      <div className="p-5 flex flex-col flex-1 gap-3">
        <h3
          className="font-serif text-xl font-bold text-white group-hover:text-amber-400 transition-colors cursor-pointer line-clamp-2"
          onClick={() => onExplore?.(asset)}
        >
          {asset.title}
        </h3>

        {/* Icon-based Details */}
        <div className="flex flex-wrap items-center gap-3 mt-auto pt-2">
          <div
            className="flex items-center gap-1.5 text-neutral-400"
            title={`Inventor: ${asset.inventor}`}
          >
            <User className="w-3.5 h-3.5 text-amber-500 shrink-0" />
            <span className="text-xs font-sans truncate max-w-[90px]">{asset.inventor}</span>
          </div>

          <div
            className="flex items-center gap-1.5 text-neutral-400"
            title={`Patent Date: ${asset.patentDate}`}
          >
            <Calendar className="w-3.5 h-3.5 text-amber-500 shrink-0" />
            <span className="text-xs font-sans">{asset.patentDate}</span>
          </div>
        </div>
      </div>

      {/* Card Footer - அனைத்து கார்டுகளிலும் ஒரே அளவில் கீழே இருக்கும் */}
      <div className="px-5 py-4 flex items-center justify-between border-t border-neutral-800/80 bg-[#0A0A0A] shrink-0">
        {/* Location */}
        <div
          className="flex items-center gap-1.5 text-neutral-500"
          title={`Location: ${asset.location}`}
        >
          <MapPin className="w-3.5 h-3.5 shrink-0" />
          <span className="font-mono text-[10px] uppercase tracking-wider truncate max-w-[90px]">
            {asset.location}
          </span>
        </div>

        {/* Actions */}
        <div className="flex items-center gap-2">
          {/* 3D Button */}
          {onExplore3D && (
            <button
              onClick={(e) => {
                e.preventDefault();
                onExplore3D(asset);
              }}
              className="p-1.5 rounded-lg bg-[#1A1A1A] hover:bg-amber-500/20 text-neutral-400 hover:text-amber-400 transition-colors border border-neutral-700 hover:border-amber-500/40"
              title="Inspect 3D"
            >
              <Box className="w-4 h-4" />
            </button>
          )}

          {/* Explore Button (Fixed Size) */}
          <Link
            href={`/inventions/${asset.id}`}
            className="flex items-center justify-center gap-1.5 px-3 py-1.5 rounded-lg bg-amber-500/10 hover:bg-amber-500/20 text-amber-500 transition-colors border border-amber-500/20 hover:border-amber-500/40"
          >
            <span className="font-sans font-semibold text-[11px] uppercase tracking-wider">
              Explore
            </span>
            <ArrowRight className="w-3.5 h-3.5" />
          </Link>
        </div>
      </div>
    </div>
  );
}
